if (points.empty()) return BoundingBox2{Point2d{0,0}, Point2d{0,0}};

// Build convex hull
std::vector<Point2d> hull;
{
    std::vector<Point2d> pts = points;
    std::sort(pts.begin(), pts.end(), [](const Point2d& a, const Point2d& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });
    for (size_t i = 0; i < pts.size(); ++i) {
        while (hull.size() >= 2) {
            Point2d a = hull[hull.size()-2];
            Point2d b = hull.back();
            Point2d c = pts[i];
            double cross = (b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x);
            if (cross <= 0) hull.pop_back();
            else break;
        }
        hull.push_back(pts[i]);
    }
    size_t lower_hull = hull.size();
    for (int i = (int)pts.size()-2; i >= 0; --i) {
        while (hull.size() > lower_hull) {
            Point2d a = hull[hull.size()-2];
            Point2d b = hull.back();
            Point2d c = pts[i];
            double cross = (b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x);
            if (cross <= 0) hull.pop_back();
            else break;
        }
        hull.push_back(pts[i]);
    }
    hull.pop_back();
}

if (hull.size() == 1) return BoundingBox2{hull[0], hull[0]};
if (hull.size() == 2) {
    Point2d minP{std::min(hull[0].x, hull[1].x), std::min(hull[0].y, hull[1].y)};
    Point2d maxP{std::max(hull[0].x, hull[1].x), std::max(hull[0].y, hull[1].y)};
    return BoundingBox2{minP, maxP};
}

double min_area = std::numeric_limits<double>::max();
BoundingBox2 best_box;

for (size_t i = 0; i < hull.size(); ++i) {
    Point2d p1 = hull[i];
    Point2d p2 = hull[(i+1)%hull.size()];
    double dx = p2.x - p1.x;
    double dy = p2.y - p1.y;
    double len = std::sqrt(dx*dx + dy*dy);
    if (len == 0) continue;
    double ux = dx / len;
    double uy = dy / len;
    double vx = -uy;
    double vy = ux;

    double min_u = 0, max_u = 0, min_v = 0, max_v = 0;
    for (const Point2d& p : hull) {
        double u = (p.x - p1.x) * ux + (p.y - p1.y) * uy;
        double v = (p.x - p1.x) * vx + (p.y - p1.y) * vy;
        if (u < min_u) min_u = u;
        if (u > max_u) max_u = u;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;
    }

    double area = (max_u - min_u) * (max_v - min_v);
    if (area < min_area) {
        min_area = area;
        Point2d center = Point2d{p1.x + ux*(min_u+max_u)/2 + vx*(min_v+max_v)/2,
                                 p1.y + uy*(min_u+max_u)/2 + vy*(min_v+max_v)/2};
        double half_width = (max_u - min_u) / 2;
        double half_height = (max_v - min_v) / 2;
        Point2d corners[4] = {
            {center.x - ux*half_width - vx*half_height, center.y - uy*half_width - vy*half_height},
            {center.x + ux*half_width - vx*half_height, center.y + uy*half_width - vy*half_height},
            {center.x + ux*half_width + vx*half_height, center.y + uy*half_width + vy*half_height},
            {center.x - ux*half_width + vx*half_height, center.y - uy*half_width + vy*half_height}
        };
        double min_x = corners[0].x, max_x = corners[0].x;
        double min_y = corners[0].y, max_y = corners[0].y;
        for (int k = 1; k < 4; ++k) {
            if (corners[k].x < min_x) min_x = corners[k].x;
            if (corners[k].x > max_x) max_x = corners[k].x;
            if (corners[k].y < min_y) min_y = corners[k].y;
            if (corners[k].y > max_y) max_y = corners[k].y;
        }
        best_box = BoundingBox2{Point2d{min_x, min_y}, Point2d{max_x, max_y}};
    }
}

return best_box;
// END_CODE

